import{_ as i,o as a,c as t,ae as o}from"./chunks/framework.1Lna8NcP.js";const u=JSON.parse('{"title":"Technical Overview","description":"","frontmatter":{},"headers":[],"relativePath":"technical.md","filePath":"technical.md"}'),l={name:"technical.md"};function c(r,e,d,n,s,p){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="technical-overview" tabindex="-1">Technical Overview <a class="header-anchor" href="#technical-overview" aria-label="Permalink to &quot;Technical Overview&quot;">​</a></h1><p>This page reflects the current implementation state as of April 2026.</p><h2 id="runtime-topology" tabindex="-1">Runtime topology <a class="header-anchor" href="#runtime-topology" aria-label="Permalink to &quot;Runtime topology&quot;">​</a></h2><ul><li>Backend: FastAPI app on <code>:8000</code></li><li>Frontend: Vite dev server on <code>:5173</code>/<code>:5174</code></li><li>Database: SQLite at <code>data/libertas.db</code></li><li>Watch folder: <code>data/watch/</code> for auto-detected imports</li><li>Docs: VitePress static site on GitHub Pages</li></ul><p>Run locally:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./start.sh</span></span></code></pre></div><h2 id="frontend-architecture" tabindex="-1">Frontend architecture <a class="header-anchor" href="#frontend-architecture" aria-label="Permalink to &quot;Frontend architecture&quot;">​</a></h2><ul><li>React 18 + TypeScript + React Router</li><li>Theme context with two UI themes: <code>onyx</code> and <code>retro</code></li><li>Major routes: <ul><li><code>/</code> Overview dashboard</li><li><code>/accounts</code></li><li><code>/import</code></li><li><code>/debt</code></li><li><code>/retirement</code></li><li><code>/real-estate</code></li><li><code>/taxes</code></li><li><code>/insights</code></li><li><code>/settings</code></li></ul></li></ul><h2 id="backend-api-map" tabindex="-1">Backend API map <a class="header-anchor" href="#backend-api-map" aria-label="Permalink to &quot;Backend API map&quot;">​</a></h2><p>All routes are mounted under <code>/api</code>.</p><ul><li><code>/accounts</code> account + institution CRUD, transactions, holdings, performance</li><li><code>/snapshots</code> current + historical net worth and snapshot recording</li><li><code>/imports</code> upload, preview, rollback</li><li><code>/watcher</code> watch-folder import logs and latest import event</li><li><code>/debt</code> debt summary, strategies, payoff chart, extra payment simulation</li><li><code>/retirement</code> projections and personalized plan endpoint</li><li><code>/taxes</code> estimate, harvesting opportunities, entity recommendations</li><li><code>/insights</code> deterministic rules + optional Claude chat</li><li><code>/news</code> cached RSS/news aggregation with refresh endpoint</li><li><code>/backups</code> local backup creation and download</li><li><code>/prices</code> holdings price refresh + status</li><li><code>/settings</code> local key-value configuration storage</li><li><code>/real-estate</code> property CRUD + valuation refresh</li><li><code>/integrations</code> optional Plaid and Sheets sync endpoints</li></ul><h2 id="data-ingest-model" tabindex="-1">Data ingest model <a class="header-anchor" href="#data-ingest-model" aria-label="Permalink to &quot;Data ingest model&quot;">​</a></h2><p>Current ingest paths:</p><ol><li>Manual account/transaction updates in-app</li><li>CSV/Excel uploads or watch-folder ingestion</li><li>Optional Plaid connection</li><li>Optional Google Sheets CSV feeds</li></ol><p>Source precedence and provenance fields are used to support deterministic dedupe/merge behavior across sources.</p><h2 id="security-model" tabindex="-1">Security model <a class="header-anchor" href="#security-model" aria-label="Permalink to &quot;Security model&quot;">​</a></h2><ul><li>Local-first storage by default</li><li>At-rest encryption for sensitive text fields (ADR-010)</li><li>Key modes: <ul><li>macOS Keychain (default)</li><li>user passphrase (Argon2id-derived key)</li></ul></li><li>AI features are optional and key-gated</li></ul><p>See <a href="/Libertas/security.html">Security &amp; Encryption</a> for full details.</p><h2 id="adr-coverage" tabindex="-1">ADR coverage <a class="header-anchor" href="#adr-coverage" aria-label="Permalink to &quot;ADR coverage&quot;">​</a></h2><p>Architecture decisions live in <a href="/Libertas/adr/">ADR Index</a>, including:</p><ul><li>Foundational app design (ADR-001)</li><li>Multi-source ingest direction (ADR-002, ADR-009)</li><li>Dashboard completion milestones (ADR-006)</li><li>Encryption at rest (ADR-010)</li></ul>',21)])])}const m=i(l,[["render",c]]);export{u as __pageData,m as default};
